/* anbot live avatar · drop-in component (sprites inlined) */
(function(){
"use strict";
var SPRITES = {"open": {"w": 289, "h": 360, "src": "data:image/webp;base64,"}, "half": {"w": 289, "h": 360, "src": "data:image/webp;base64,"}, "closed": {"w": 289, "h": 360, "src": "data:image/webp;base64,"}, "left": {"w": 289, "h": 360, "src": "data:image/webp;base64,"}, "right": {"w": 289, "h": 360, "src": "data:image/webp;base64,"}, "mouth": {"w": 289, "h": 360, "src": "data:image/webp;base64,"}, "surprise": {"w": 289, "h": 360, "src": "data:image/webp;base64,"}, "wink": {"w": 289, "h": 360, "src": "data:image/webp;base64,"}, "smile": {"w": 289, "h": 360, "src": "data:image/webp;base64,"}, "pout": {"w": 289, "h": 360, "src": "data:image/webp;base64,"}, "up": {"w": 289, "h": 360, "src": "data:image/webp;base64,"}};
var STATES={idle:{label:"idle · 待机"},thinking:{label:"thinking · 思考"},working:{label:"working · 执行"},done:{label:"done · 完成"},happy:{label:"happy · 开心"},sleepy:{label:"sleepy · 睡眠"},surprised:{label:"surprised · 惊讶"},look:{label:"look · 巡视"},nod:{label:"nod · 点头"},error:{label:"error · 异常"}};
var BASE={sleepy:"closed",surprised:"surprise",happy:"mouth",done:"smile",thinking:"up"};

var instances=[], rafId=null, pageHidden=false;
function tick(){
  rafId=null;
  for(var i=0;i<instances.length;i++) instances[i].frame();
  if(instances.length) rafId=requestAnimationFrame(tick);
}
function ensureLoop(){ if(!rafId && !pageHidden && instances.length) rafId=requestAnimationFrame(tick); }
document.addEventListener("visibilitychange",function(){ pageHidden=document.hidden; if(pageHidden){ if(rafId){cancelAnimationFrame(rafId); rafId=null;} } else ensureLoop(); });

function AnbotAvatar(canvas,opts){
  opts=opts||{};
  this.cv=canvas; this.ctx=canvas.getContext("2d");
  this.crop=opts.crop||"full"; this.zoom=opts.zoom||(this.crop==="head"?1.08:1);
  this.focus=this.crop==="head"?0.25:null; this.shadow=opts.shadow!==false;
  this.state=STATES[opts.state]?opts.state:"idle"; this.onReact=opts.onReact||null; this.paused=false; this.t0=performance.now(); this.last=0;
  this.visible=true; this.destroyed=false;
  this.ac=new AbortController(); var sig={signal:this.ac.signal};
  var mq=window.matchMedia&&window.matchMedia("(prefers-reduced-motion: reduce)");
  this.reduce=!!(mq&&mq.matches); var self=this;
  if(mq&&mq.addEventListener) mq.addEventListener("change",function(e){ self.reduce=e.matches; },sig);

  this.motion=Object.assign({breath:1,sway:1,tempo:1,blinkMin:2.2,blinkMax:5.8,eventGap:10},opts.motion||{});
  this.blinkAt=-1; this.blinkDur=0.16; this.nextBlink=this.motion.blinkMin+Math.random()*(this.motion.blinkMax-this.motion.blinkMin);
  this.moves=opts.moves||{}; this.move=null; this.moveStart=0; this.moveFace=null; this.moveName=""; this.onMoveEnd=opts.onMoveEnd||null;
  this.mv={rot:0,lean:0,lift:0,squash:0,dy:0,ds:0,sx:0};
  this.blend=null; this.poseBlink=null; this.lastKey=null; this.blendDur=opts.blendDur||0.34; this.blendBack=opts.blendBack||0.24; this.inBlendDur=opts.inBlendDur||0.12; this.endBlendDur=opts.endBlendDur||0.18;
  this.face=BASE[this.state]||"open"; this.pending=null; this.pendingSince=0;
  this.nextFace=9+Math.random()*6; this.faceUntil=-1; this.oneShot=null;
  this.evRot=0; this.evLean=0; this.evLift=0; this.evUntil=-1; this.nextEv=10+Math.random()*8;
  this.hover=false; this.press=false; this.px=0; this.py=0; this.hoverFace=null;
  this.reactUntil=0; this.reactFace="open"; this.lastReact=-1;
  this.p={rot:0,lean:0,lift:0,squash:0,shear:0,bend:0}; this.v={rot:0,lean:0,lift:0,squash:0,shear:0,bend:0};

  this.imgs={}; this.loaded=0; this.failed=0;
  var srcMap=opts.sprites||SPRITES, keys=Object.keys(srcMap);
  keys.forEach(function(k){
    var v=srcMap[k], im=new Image();
    im.onload=function(){ self.loaded++; };
    im.onerror=function(){ self.failed++; };
    im.src=(typeof v==="string")?v:(v&&v.src)||"";
    self.imgs[k]=im;
  });

  this.resize();
  this.ro=window.ResizeObserver?new ResizeObserver(function(){ self.resize(); }):null;
  if(this.ro) this.ro.observe(canvas);
  window.addEventListener("resize",function(){ self.resize(); },sig);

  if(opts.interactive!==false) canvas.style.cursor="pointer";
  canvas.style.touchAction="manipulation";
  if(opts.interactive!==false){
    canvas.setAttribute("tabindex","0");
    canvas.setAttribute("role","button");
    canvas.setAttribute("aria-label",opts.label||"anbot 头像，点击会有反应");
  }
  function norm(e){ var r=canvas.getBoundingClientRect(); self.px=((e.clientX-r.left)/r.width-0.5)*2; self.py=((e.clientY-r.top)/r.height-0.5)*2; }
  function react(){
    var nowT=self.now();
    if(nowT-self.lastReact<0.32) return;
    self.lastReact=nowT;
    var opts2=["surprise","wink","smile"], pick=opts2[Math.floor(Math.random()*opts2.length)];
    self.reactFace=pick; self.reactUntil=self.now()+0.85;
    self.v.lift+=(self.reduce?0.2:0.55); self.v.squash+=(self.reduce?0.06:0.20);
    self.clampV();
    if(self.onReact) self.onReact(self.state);
  }
  if(opts.interactive!==false){
  canvas.addEventListener("pointerenter",function(e){ if(e.pointerType==="touch") return; self.hover=true; norm(e); self.pickHoverFace(); },sig);
  canvas.addEventListener("pointermove",function(e){ if(e.pointerType==="touch") return; norm(e); if(self.hover) self.pickHoverFace(); },sig);
  canvas.addEventListener("pointerleave",function(){ self.hover=false; self.press=false; self.hoverFace=null; self.px=0; self.py=0; },sig);
  canvas.addEventListener("pointerdown",function(e){ if(e.pointerType==="touch") norm(e); self.press=true; },sig);
  canvas.addEventListener("pointerup",function(){ self.press=false; },sig);
  canvas.addEventListener("pointercancel",function(){ self.press=false; self.hover=false; },sig);
  canvas.addEventListener("click",react,sig);
  canvas.addEventListener("dblclick",function(){ self.reactFace="mouth"; self.reactUntil=self.now()+1.1; self.v.lift+=(self.reduce?0.12:0.35); self.v.squash-=(self.reduce?0.03:0.10); self.clampV(); },sig);
  canvas.addEventListener("keydown",function(e){ if(e.repeat) return; if(e.key==="Enter"||e.key===" "){ e.preventDefault(); react(); } },sig);
  }

  if(window.IntersectionObserver){
    this.io=new IntersectionObserver(function(es){ es.forEach(function(x){ self.visible=x.isIntersecting; }); },{threshold:0.02});
    this.io.observe(canvas);
  }
  instances.push(this); ensureLoop();
}
AnbotAvatar.prototype.now=function(){ return (performance.now()-this.t0)/1000; };
// 根据所在容器的底色自动换影子：浅底用软灰，深底用墨黑
AnbotAvatar.prototype.ink=function(){
  if(this._ink) return this._ink;
  var node=this.cv.parentElement, bg=null;
  while(node){ var c=getComputedStyle(node).backgroundColor; if(c&&c!=="rgba(0, 0, 0, 0)"&&c!=="transparent"){ bg=c; break; } node=node.parentElement; }
  var lum=0.08;
  if(bg){ var m=bg.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)(?:,\s*([\d.]+))?/); if(m){ var r=+m[1],g=+m[2],b=+m[3],al=m[4]?+m[4]:1; lum=((0.299*r+0.587*g+0.114*b)/255)*al+(1-al)*0.05; } }
  this._ink = lum>0.5 ? {rgb:"84,77,66", a:0.26} : {rgb:"2,5,11", a:0.66};
  return this._ink;
};
AnbotAvatar.prototype.clampV=function(){
  var lim={rot:0.5,lean:0.06,lift:0.5,squash:0.22,shear:3,bend:0.02};
  for(var k in this.v){ if(this.v[k]>lim[k]) this.v[k]=lim[k]; if(this.v[k]<-lim[k]) this.v[k]=-lim[k]; }
};
AnbotAvatar.prototype.pickHoverFace=function(){
  if(this.px>0.30) this.hoverFace="right"; else if(this.px<-0.30) this.hoverFace="left"; else if(Math.abs(this.px)<0.16) this.hoverFace=null;
};
AnbotAvatar.prototype.setState=function(s){
  if(!STATES[s]) return this;
  if(s===this.state) return this;
  this.state=s; this.switchT=this.now(); this.face=BASE[s]||"open"; this.pending=null;
  if(this.move && this.onMoveEnd) this.onMoveEnd(this.moveName);
  this.move=null; this.moveFace=null; this.mv={rot:0,lean:0,lift:0,squash:0,dy:0,ds:0,sx:0};
  this.faceUntil=-1; this.nextFace=this.now()+3.2+Math.random()*2.5;
  if(s==="surprised"){ this.v.lift+=(this.reduce?0.2:0.6); this.clampV(); }
  if(s==="done"||s==="happy"){ this.v.lift+=(this.reduce?0.12:0.32); this.oneShot={at:this.now()+2.4,face:"wink"}; this.clampV(); }
  if(s==="error"){ this.v.rot+=(this.reduce?0.2:0.6); this.clampV(); }
  return this;
};
AnbotAvatar.prototype.resize=function(){
  var dpr=(window.devicePixelRatio||1), r=this.cv.getBoundingClientRect();
  if(!r.width||!r.height) return;
  this._ink=null;
  var w=Math.round(r.width*dpr), h=Math.round(r.height*dpr);
  if(this.cv.width!==w||this.cv.height!==h){ this.cv.width=w; this.cv.height=h; }
};
AnbotAvatar.prototype.frame=function(){ if(this.destroyed||!this.visible||this.paused) return; this.draw(); };
AnbotAvatar.prototype.pause=function(){ this.paused=true; };
AnbotAvatar.prototype.resume=function(){ this.paused=false; this.last=this.now(); };
AnbotAvatar.prototype.destroy=function(){
  this.destroyed=true;
  try{ this.ac.abort(); }catch(e){}
  if(this.ro) this.ro.disconnect();
  if(this.io) this.io.disconnect();
  var i=instances.indexOf(this); if(i>=0) instances.splice(i,1);
  this.imgs={}; this._lastBase=null; this.move=null; this.moveFace=null; this.blend=null; this.lastKey=null;
  if(this.cv){ this.cv.style.cursor=""; this.cv.removeAttribute("tabindex"); this.cv.removeAttribute("role"); }
};

AnbotAvatar.prototype.targets=function(t){
  var mo=this.motion||{breath:1,sway:1,tempo:1};
  var drift=0.55*Math.sin(2*Math.PI*0.011*t)+0.28*Math.sin(2*Math.PI*0.0047*t+1.3);
  var wb=2*Math.PI*0.20*mo.tempo*(t+drift*1.4), wsw=2*Math.PI*0.050*mo.tempo*t+drift*0.8*mo.sway, wp=2*Math.PI*0.33*t;
  var s=this.state, T={rot:0,lean:0,lift:0,squash:0.011*Math.sin(wb)};
  if(s==="idle"){
    var env=0.72+0.28*Math.sin(2*Math.PI*0.011*t);
    T.rot=0.017*Math.sin(wsw+0.6)+0.005*Math.sin(2*Math.PI*0.017*t+2.1);
    T.squash=0.012*Math.sin(wb)*env;
    T.lift=0.004*Math.sin(wb+0.5)*env;
    T.lean=0.008*Math.sin(2*Math.PI*0.043*t+1.1)+0.003*Math.sin(2*Math.PI*0.028*t+0.4);
    if(t>this.nextEv && this.evUntil<0){
      if(Math.random()<0.38){ this.evLift=0.016; this.evRot=0; this.evLean=0; }
      else { this.evLift=0; this.evRot=(Math.random()<0.5?-1:1)*0.028; this.evLean=(Math.random()<0.5?-1:1)*0.010; }
      this.evUntil=t+1.7+Math.random()*0.9; this.nextEv=t+10+Math.random()*8;
    }
    if(this.evUntil>0 && t>this.evUntil){ this.evRot=0; this.evLean=0; this.evLift=0; this.evUntil=-1; }
    T.rot+=this.evRot; T.lean+=this.evLean; T.lift+=this.evLift;
  } else if(s==="thinking"){
    T.rot=0.034+0.010*Math.sin(2*Math.PI*0.07*t); T.lean=-0.004; T.squash=0.004*Math.sin(wb*1.2);
  } else if(s==="working"){
    var bump=function(x,w){ return x>=0&&x<=w?Math.pow(Math.sin(Math.PI*x/w),0.9):0; };
    var u=t%(1.2/mo.tempo), e1=bump(u,0.18), e2=bump(u-0.34,0.18), e3=bump(u-0.70,0.24);
    var eff=Math.min(1,0.55*e1+0.72*e2+0.95*e3);
    this._workEff=eff;
    T.rot=0.020+0.010*Math.sin(2*Math.PI*0.42*t); T.lean=0.005*Math.sin(2*Math.PI*0.55*t+0.6);
  } else if(s==="done"||s==="happy"){
    var hop=Math.max(0,Math.sin(2*Math.PI*0.62*t)); T.lift=hop*hop*0.050; T.squash=0.010*hop; T.rot=0.014*Math.sin(2*Math.PI*0.30*t);
  } else if(s==="sleepy"){ T.rot=-0.03; T.lean=0.006; T.squash=0.012*Math.sin(2*Math.PI*0.085*t); }
  else if(s==="surprised"){ T.rot=-0.008; T.squash=-0.014; }
  else if(s==="nod"){
    var bump=function(x,w){ return x>=0&&x<=w?Math.pow(Math.sin(Math.PI*x/w),1.25):0; };
    var uc=t%(3.2/mo.tempo);
    var d=Math.min(1,bump(uc,0.22)+bump(uc-0.40,0.22)+bump(uc-0.80,0.22));
    this._nodDip=d;
    T.rot=0.004*d; T.lean=0.002*d;
  }
  else if(s==="look"){
    var g=this.scanPhase(t);
    if(g!==this._scanG){ this._scanG=g; if(g!==0 && this.blinkAt<0){ this.blinkAt=t; this.blinkDur=0.14; } }
    T.rot=0.055*g+0.006*Math.sin(2*Math.PI*0.23*t); T.lean=0.020*g+0.003*Math.sin(2*Math.PI*0.19*t+0.7);
    T.lift=0.003*Math.abs(g); T.squash=0.004*Math.sin(wb)*0.6;
  }
  else if(s==="error"){ T.rot=0.012*Math.sin(2*Math.PI*2.6*t); T.lean=0.003*Math.sin(2*Math.PI*3.4*t); }
  if(s==="idle"||s==="sleepy"){ T.squash*=mo.breath; T.rot*=mo.sway; T.lean*=mo.sway; T.lift*=mo.breath; }
  T.shear=-(T.rot*57.3)*1.15 + 0.3*Math.sin(wsw*1.2);
  T.bend=-(T.rot*0.55) + 0.0016*Math.sin(wsw*1.7);
  var f=this.face;
  if(t<this.reactUntil) f=this.reactFace;
  if(f==="smile"||f==="wink"){ T.rot+=0.010; T.lift+=0.004; }
  else if(f==="mouth"){ T.rot-=0.008; T.lift+=0.010; }
  else if(f==="up"){ T.rot-=0.006; }
  if(this.reduce){ T.rot*=0.3; T.lean*=0.3; T.lift*=0.3; T.squash*=0.3; T.shear*=0.3; }
  return T;
};
AnbotAvatar.prototype.step=function(dt,T){
  var K={rot:52,lean:48,lift:78,squash:95,shear:26,bend:18}, D={rot:11,lean:10,lift:12,squash:15,shear:8.5,bend:6.5};
  var n=Math.max(1,Math.ceil(dt/0.008)), h=dt/n;
  var P={rot:0.20,lean:0.06,lift:0.045,squash:0.06,shear:2.4,bend:0.02};
  for(var i=0;i<n;i++){
    for(var k in this.p){
      var a=(T[k]-this.p[k])*K[k]-this.v[k]*D[k]; this.v[k]+=a*h; this.p[k]+=this.v[k]*h;
      if(this.p[k]>P[k]){ this.p[k]=P[k]; if(this.v[k]>0) this.v[k]=0; }
      if(this.p[k]<(k==="lift"?-0.004:-P[k])){ this.p[k]=(k==="lift"?-0.004:-P[k]); if(this.v[k]<0) this.v[k]=0; }
    }
  }
};

AnbotAvatar.prototype.scanPhase=function(t){
  var u=t%(4.8/((this.motion&&this.motion.tempo)||1));
  if(u<0.9) return 0;
  if(u<2.0) return -1;
  if(u<2.5) return 0;
  if(u<3.6) return 1;
  return 0;
};

AnbotAvatar.prototype.planFace=function(t){
  if(this.pending) return;
  var st=this.state;
  if(st==="look"){
    var g=this.scanPhase(t), want=g<0?"left":(g>0?"right":"open");
    if(this.blinkAt<0 && this.face!==want && this.face!=="half") this.face=want;
    return;
  }
  if(st==="working"){ if(this.blinkAt<0 && this.face!=="open" && this.face!=="half") this.face="open"; return; }
  if(st==="nod") return;
  if(this.faceUntil>0 && t>this.faceUntil){ this.faceUntil=-1; this.pending="base"; this.pendingSince=t; this.nextFace=t+3.2+Math.random()*3.2; return; }
  if(t>this.nextFace){
    var s=this.state,pick;
    if(s==="idle"){ var r=Math.random(); pick=r<0.46?"smile":(r<0.68?"left":(r<0.9?"right":"wink")); }
    else if(s==="thinking"){ pick=Math.random()<0.75?"up":"smile"; }
    else if(s==="working"){ pick=Math.random()<0.45?"left":(Math.random()<0.55?"right":"open"); }
    else if(s==="done"){ pick=Math.random()<0.6?"wink":"smile"; }
    else if(s==="nod"){ pick="open"; }
    else return;
    this.pending=pick; this.pendingSince=t; this.faceUntil=0;
  }
};

// 专属动作：关键帧只为身体通道叠加偏移，不改状态机
AnbotAvatar.prototype.sampleMove=function(t){
  var mv=this.mv, m=this.move;
  mv.rot=mv.lean=mv.lift=mv.squash=mv.dy=mv.ds=mv.sx=0; this.moveFace=null;
  if(!m) return;
  var u=t-this.moveStart, k=m.keyframes, dur=m.duration||k[k.length-1].t;
  if(u<0) return;
  if(u>=dur){ this.move=null; if(this.onMoveEnd) this.onMoveEnd(this.moveName); return; }
  var i=0; while(i<k.length-1 && u>k[i+1].t) i++;
  var a=k[i], b=k[Math.min(i+1,k.length-1)];
  var span=Math.max(0.000001,b.t-a.t), q=Math.max(0,Math.min(1,(u-a.t)/span));
  q=q*q*(3-2*q);
  var L=function(x,y){ var xa=x||0, ya=(y===undefined?x:y)||0; return xa+(ya-xa)*q; };
  mv.rot=L(a.rot,b.rot); mv.lean=L(a.lean,b.lean); mv.lift=L(a.lift,b.lift);
  mv.squash=L(a.squash,b.squash); mv.dy=L(a.dy,b.dy); mv.ds=L(a.ds,b.ds); mv.sx=L(a.sx,b.sx);
  var face=null;
  for(var j=0;j<k.length;j++){ if(k[j].t<=u && k[j].face!==undefined) face=k[j].face; }
  if(m.faceTrack){
    face=m.faceTrack[0].face;
    for(var f=0;f<m.faceTrack.length;f++){
      var ent=m.faceTrack[f];
      // 目标时间点完全到位：过程帧提前一个交叉时长开始淡入，避免身体先到、姿势后追
      var lead=ent.lead!==undefined?ent.lead:(ent.face==="sig"?this.endBlendDur:this.inBlendDur);
      if(ent.t-lead<=u) face=ent.face;
    }
  }
  this.moveFace=face;
};
AnbotAvatar.prototype.play=function(move){
  if(typeof move==="string") move=this.moves[move];
  if(!move||!move.keyframes||!move.keyframes.length) return this;
  this.move=move; this.moveStart=this.now(); this.moveName=move.name||"";
  this.poseBlink=null;
  if(!move.faceTrack && move.blinkBridge!==false){
    for(var i=0;i<move.keyframes.length;i++){ if(move.keyframes[i].face==="sig"){ var ts=move.keyframes[i].t; this.poseBlink={start:Math.max(0,ts-0.12),end:Math.max(0,ts-0.015)}; break; } }
  }
  this.blinkAt=-1; this.pending=null; this.faceUntil=-1;
  return this;
};

// 把整张图按横向条带做轻微弯折，模拟纸片被风吹/被带动时的滞后
AnbotAvatar.prototype.paper=function(img,bend,t){
  var w=img.width, h=img.height;
  if(!this.pCv){ this.pCv=document.createElement("canvas"); this.pCtx=this.pCv.getContext("2d"); }
  if(this.pCv.width!==w||this.pCv.height!==h){ this.pCv.width=w; this.pCv.height=h; }
  var c=this.pCtx;
  c.clearRect(0,0,w,h);
  var amp=bend*h;                       // 顶部最大偏移（像素）
  if(Math.abs(amp)<0.6){ c.drawImage(img,0,0); return this.pCv; }
  var N=26, sh=h/N;
  for(var i=0;i<N;i++){
    var y0=i*sh, yy=y0+h*0.5;
    var k=1-yy/h;                       // 0 底 → 1 顶
    var dx=amp*Math.pow(k,1.55) + Math.sin(t*1.6-yy/h*3.1)*0.0018*h*k;
    c.drawImage(img, 0, y0, w, sh+1, dx, y0, w, sh+1);
  }
  return this.pCv;
};

AnbotAvatar.prototype.draw=function(){
  var ctx=this.ctx, W=this.cv.width, H=this.cv.height, t=this.now();
  var dt=Math.min(0.05,Math.max(0.001,t-this.last)); this.last=t;
  if(!W||!H) return;
  ctx.clearRect(0,0,W,H);
  var ax=W*0.5, ay=H*0.986, S=0.93;
  var T=this.targets(t);
  this.sampleMove(t);
  T.rot+=this.mv.rot; T.lean+=this.mv.lean; T.lift+=this.mv.lift; T.squash+=this.mv.squash;
  if(this.hover){ T.rot+=this.px*0.060; T.lean+=this.px*0.012; T.lift+=0.011; T.squash+=0.008; }
  if(this.press){ T.squash+=0.045; T.lean-=this.px*0.004; }
  if(t<this.reactUntil) T.rot+=0.012;
  if(this.reduce){ T.lift*=0.3; T.squash*=0.3; T.rot*=0.3; T.lean*=0.3; }
  this.step(dt,T); var p=this.p;

  var canBlink=!this.move&&!(this.state==="sleepy"||this.state==="happy"||this.state==="nod");
  var stage=0, drop=0;
  if(canBlink){
    if(this.blinkAt<0 && t>this.nextBlink){ this.blinkAt=t; this.blinkDur=(Math.random()<0.12?0.26:0.15)+Math.random()*0.04; }
    if(this.blinkAt>=0){
      var e=(t-this.blinkAt)/this.blinkDur;
      if(e>=1){
        this.blinkAt=-1;
        var r=Math.random();
        var bm=this.motion||{blinkMin:2.2,blinkMax:5.8};
        this.nextBlink = t + (r<0.18 ? 0.36 : (r<0.26 ? 7.5+Math.random()*2.5 : bm.blinkMin+Math.random()*(bm.blinkMax-bm.blinkMin)));
      }
      else stage=e<0.18?1:(e<0.72?2:(e<0.9?1:0));
      if(stage===2 && this.pending){
        this.face=this.pending==="base"?(BASE[this.state]||"open"):this.pending;
        this.pending=null;
        this.faceUntil=this.face==="smile"?t+3.2+Math.random()*2.2:(this.face==="left"||this.face==="right"?t+0.6+Math.random()*0.5:(this.face==="wink"?t+0.8:0));
      }
    }
    if(stage) drop=H*(stage===1?0.004:0.008);
    if(this.pending && this.blinkAt<0 && t-this.pendingSince>2.0){ this.blinkAt=t; this.blinkDur=0.16; }
  }
  this.planFace(t);
  if(this.oneShot && t>this.oneShot.at && !this.pending){ this.pending=this.oneShot.face; this.pendingSince=t; this.oneShot=null; }

  var dSq=(this.state==="nod"?-0.042*(this._nodDip||0):(this.state==="working"?-0.060*(this._workEff||0):0))+this.mv.ds;
  var dLift=0;
  var lift=Math.max(0,p.lift+dLift), sq=1-Math.min(0.5,Math.abs(p.squash+dSq)*3);
  var shw=W*0.30*sq*(1-0.45*Math.min(1,lift/0.06)), shh=shw*0.10;
  if(!this.shadow || this.focus!==null){ } else {
  var ink=this.ink(), grd=ctx.createRadialGradient(ax,ay,0,ax,ay,shw);
  grd.addColorStop(0,"rgba("+ink.rgb+","+ink.a+")");
  grd.addColorStop(0.55,"rgba("+ink.rgb+","+(ink.a*0.52)+")");
  grd.addColorStop(1,"rgba("+ink.rgb+",0)");
  ctx.save(); ctx.translate(ax,ay+shh*0.3); ctx.scale(1,shh/shw);
  ctx.beginPath(); ctx.arc(0,0,shw,0,Math.PI*2); ctx.fillStyle=grd; ctx.fill(); ctx.restore();
  }

  var faceKey=this.face;
  if(t<this.reactUntil) faceKey=this.reactFace;
  else if(this.hover && this.hoverFace) faceKey=this.hoverFace;
  if(this.moveFace && this.imgs[this.moveFace] && this.imgs[this.moveFace].naturalWidth) faceKey=this.moveFace;
  var key=stage===1?"half":(stage===2?"closed":faceKey);
  var mt=t-this.moveStart;
  if(this.move && this.poseBlink && mt>=this.poseBlink.start && mt<=this.poseBlink.end) key="closed";
  var PK=function(k){return k==="sig"||k==="p0"||k==="p1"||k==="p2"||k==="p3";};
  if(this.lastKey && key!==this.lastKey && (PK(key)||PK(this.lastKey))){
    var bdur=0.12;
    if(key==="sig") bdur=(PK(this.lastKey)?this.endBlendDur:this.blendDur);
    else if(this.lastKey==="sig") bdur=this.inBlendDur;
    else bdur=this.inBlendDur;
    this.blend={from:this.lastKey,to:key,t0:t,dur:bdur};
  }
  this.lastKey=key;
  var base=this.imgs[key]||this._lastBase||this.imgs.open;
  if(base&&base.width) this._lastBase=base;

  if(!base||!base.width||!base.naturalWidth){
    if(!this.failed) return;   // 还在加载中：先留空，别闪占位
    // 素材加载失败时的兜底：不空场
    var r=Math.min(W,H)*0.16;
    ctx.save(); ctx.translate(ax,ay);
    ctx.fillStyle="#2E9FBF"; ctx.beginPath();
    if(ctx.roundRect) ctx.roundRect(-r,-r*1.2,r*2,r*2.4,r*0.5); else ctx.rect(-r,-r*1.2,r*2,r*2.4);
    ctx.fill();
    ctx.fillStyle="#0B0C0E"; ctx.beginPath(); ctx.arc(-r*0.35,-r*0.2,r*0.18,0,Math.PI*2); ctx.arc(r*0.35,-r*0.2,r*0.18,0,Math.PI*2); ctx.fill();
    ctx.restore(); return;
  }
  var pivotY=ay-H*0.085, self=this;
  var drawFrame=function(img,alpha){
    if(!img||!img.width) return;
    var dh=H*S*self.zoom, dw=dh*img.width/img.height;
    var shiftY=self.focus!==null ? (H*0.5-ay+dh*(1-self.focus)) : 0;
    ctx.globalAlpha=Math.max(0,Math.min(1,alpha));
    ctx.drawImage(img,-dw/2,(ay-pivotY)-dh+shiftY,dw,dh);
  };
  // 姿势帧之间做交叉淡入，避免整张图硬切
  var q=1, fromImg=null;
  if(this.blend){
    var bt=(t-this.blend.t0)/this.blend.dur;
    if(bt>=1) this.blend=null;
    else { q=bt*bt*(3-2*bt); fromImg=this.imgs[this.blend.from]||this._lastBase||this.imgs.open; }
  }
  ctx.save();
  ctx.translate(ax+p.lean*W, pivotY-(p.lift+dLift)*H+drop+this.mv.dy*H);
  ctx.rotate(p.rot);
  ctx.transform(1,0,Math.tan(p.shear*Math.PI/180),1,0,0);
  var sqT=Math.min(0.09,Math.max(-0.06,p.squash+dSq)); ctx.scale((1-sqT*0.55)*(1+this.mv.sx), 1+sqT);
  if(fromImg && q<1) drawFrame(fromImg,1);
  drawFrame(base,q);
  ctx.globalAlpha=1;
  ctx.restore();
};

window.AnbotAvatar=AnbotAvatar;
window.AnbotAvatar.version="v8.4";
window.AnbotAvatar=AnbotAvatar;
AnbotAvatar.states=Object.keys(STATES);
AnbotAvatar.STATES=STATES;
})();
